# [674] 最长连续递增序列
#


# @lcpr-template-start

# @lcpr-template-end
# @lc code=start
class Solution:
    def findLengthOfLCIS(self, nums: List[int]) -> int:
        max_count = 0
        count = 1
        length = len(nums)
        for right in range(1, length):
            if nums[right] <= nums[right - 1]:
                max_count = max(count, max_count)
                count = 1

            if nums[right] > nums[right - 1]:
                count += 1
        max_count = max(count, max_count)
        return max_count

# @lc code=end


